create table public.demo_personas (
 id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
 description text not null, category text not null check(category in ('realistic','cyborg','cartoon','anime','fantasy','sci-fi','robot')),
 style text not null, preview_image_url text not null, thumbnail_url text not null,
 face_asset_reference text, voice_asset_reference text, gender_presentation text, tags text[] not null default '{}',
 active boolean not null default true, featured boolean not null default false, sort_order int not null default 0,
 inference_ready boolean not null default false, face_ready boolean not null default false, voice_ready boolean not null default false,
 metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(not inference_ready or (face_ready and face_asset_reference is not null and metadata->>'placeholder' is distinct from 'true')),
 check(not voice_ready or voice_asset_reference is not null)
);
create index demo_library_order on public.demo_personas(active,sort_order);
create index demo_featured_order on public.demo_personas(featured,sort_order) where active;
create trigger touch_demo before update on public.demo_personas for each row execute function public.touch_updated_at();
alter table public.demo_personas enable row level security;
revoke all on public.demo_personas from anon,authenticated;
-- Asset references are server-only even for shared demo identities.
grant select(id,name,slug,description,category,style,preview_image_url,thumbnail_url,gender_presentation,tags,active,featured,sort_order,inference_ready,face_ready,voice_ready,metadata,created_at,updated_at) on public.demo_personas to authenticated;
create policy demo_read on public.demo_personas for select to authenticated using(active);

alter table public.live_sessions drop constraint live_sessions_persona_id_user_id_fkey;
alter table public.live_sessions alter column persona_id drop not null;
alter table public.live_sessions add column demo_persona_id uuid references public.demo_personas(id);
alter table public.live_sessions add constraint session_custom_owner foreign key(persona_id,user_id) references public.personas(id,user_id) on delete cascade;
alter table public.live_sessions add constraint session_identity check((persona_id is not null)::int + (demo_persona_id is not null)::int = 1);
create table public.demo_trials(user_id uuid primary key references auth.users on delete cascade, session_id uuid unique references public.live_sessions(id), started_at timestamptz not null default now(), completed_at timestamptz);
alter table public.demo_trials enable row level security;
revoke all on public.demo_trials from anon,authenticated;
grant select on public.demo_trials to authenticated;
create policy own_trial on public.demo_trials for select to authenticated using(user_id=(select auth.uid()));
create table public.demo_analytics(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, demo_persona_id uuid references public.demo_personas(id), event text not null check(event in ('demo_persona_viewed','demo_persona_selected','demo_studio_started','demo_trial_completed','demo_to_custom_persona_clicked','demo_to_paid_conversion')), session_id uuid references public.live_sessions(id), created_at timestamptz not null default now());
create unique index demo_session_event_once on public.demo_analytics(session_id,event) where session_id is not null;
create index demo_analytics_owner on public.demo_analytics(user_id,created_at);
alter table public.demo_analytics enable row level security;
revoke all on public.demo_analytics from anon,authenticated;

-- Reserve a one-time 60-second trial atomically with readiness and active-session checks.
create function public.begin_demo_trial(owner_id uuid, demo_id uuid, session_metadata jsonb) returns public.live_sessions language plpgsql security definer set search_path='' as $$
declare d public.demo_personas; s public.live_sessions;
begin
 perform 1 from public.profiles where id=owner_id for update;
 if not found then raise exception 'Account not found'; end if;
 if exists(select 1 from public.demo_trials where user_id=owner_id) then raise exception 'Demo trial already used'; end if;
 select * into d from public.demo_personas where id=demo_id for share;
 if not found or not d.active or not d.inference_ready or not d.face_ready or d.face_asset_reference is null or d.metadata->>'placeholder'='true' then raise exception 'Demo is preview only'; end if;
 insert into public.live_sessions(user_id,demo_persona_id,metadata) values(owner_id,demo_id,session_metadata || jsonb_build_object('trial',true,'watermark',true,'expires_at',now()+interval '60 seconds')) returning * into s;
 insert into public.demo_trials(user_id,session_id) values(owner_id,s.id);
 return s;
end $$;
revoke execute on function public.begin_demo_trial(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.begin_demo_trial(uuid,uuid,jsonb) to service_role;

create or replace function public.finish_session(session_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare s public.live_sessions; seconds int;
begin
 select * into s from public.live_sessions where id=session_id for update;
 if not found or s.status in ('stopped','failed') then return; end if;
 seconds=greatest(0,extract(epoch from(least(now(),coalesce((s.metadata->>'expires_at')::timestamptz,now()))-coalesce(s.started_at,now())))::int);
 update public.live_sessions set status='stopped',ended_at=now(),duration_seconds=seconds where id=session_id;
 if s.metadata->>'trial'='true' then
  update public.demo_trials set completed_at=now() where user_id=s.user_id and session_id=s.id;
  insert into public.demo_analytics(user_id,demo_persona_id,event,session_id) values(s.user_id,s.demo_persona_id,'demo_trial_completed',s.id) on conflict do nothing;
 else
  insert into public.usage_events(user_id,live_session_id,event_type,quantity) values(s.user_id,s.id,'stream_minutes',seconds/60.0) on conflict do nothing;
 end if;
end $$;

